using System;using System.Linq;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using UnityEngine.SceneManagement;using UnityEditor;using DeliveryRider;using Newtonsoft.Json;
public static class DayLightingInspect{public static string Read(){var scene=SceneManager.GetActiveScene();var roots=scene.GetRootGameObjects();var renderers=roots.SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).ToArray();var rp=GraphicsSettings.currentRenderPipeline as UniversalRenderPipelineAsset;return JsonConvert.SerializeObject(new{scene=scene.path,dirty=scene.isDirty,ambient=RenderSettings.ambientMode.ToString(),ambientColor=RenderSettings.ambientLight.ToString(),fog=RenderSettings.fog,fogEnd=RenderSettings.fogEndDistance,sky=RenderSettings.skybox?.name,sun=RenderSettings.sun?.name,lights=roots.SelectMany(g=>g.GetComponentsInChildren<Light>(true)).Select(l=>new{l.name,l.enabled,l.intensity,color=l.color.ToString(),rotation=l.transform.eulerAngles.ToString(),shadows=l.shadows.ToString(),l.shadowStrength,l.shadowBias,l.shadowNormalBias,l.cullingMask}),daySkies=roots.SelectMany(g=>g.GetComponentsInChildren<DaySky>(true)).Select(s=>new{s.name,s.enabled,fields=EditorJsonUtility.ToJson(s)}),rp=rp==null?null:new{path=AssetDatabase.GetAssetPath(rp),rp.supportsMainLightShadows,rp.mainLightShadowmapResolution,rp.shadowDistance,rp.shadowCascadeCount,rp.supportsSoftShadows},materials=renderers.SelectMany(r=>r.sharedMaterials).Where(m=>m!=null).Distinct().GroupBy(m=>m.shader.name).Select(g=>new{shader=g.Key,names=g.Select(m=>m.name).ToArray()}),buildings=renderers.Where(r=>r.name.StartsWith("AB01_")).GroupBy(r=>new{r.shadowCastingMode,r.receiveShadows}).Select(g=>new{state=g.Key,count=g.Count()})});}}
